$2("setBtn").addEventListener("click", () => openMainMenu());
function offerFile(file, title, msg, onDone) {
  const nav = navigator;
  const canShare = typeof navigator.share === "function" && !!nav.canShare?.({ files: [file] });
  const box = document.createElement("div");
  box.className = "offer";
  box.innerHTML = `<div class="offer-card"><div class="offer-title">${title}</div><div class="offer-msg">${msg}</div><div class="offer-btns">` + (canShare ? `<button class="btn primary" data-v="share">\u5206\u4EAB</button>` : "") + `<button class="btn${canShare ? "" : " primary"}" data-v="download">\u4E0B\u8F7D</button><button class="btn" data-v="close">\u5173</button></div></div>`;
  document.body.append(box);
  const close = () => {
    box.remove();
    closeOffer = null;
    scoreEl.focus();
  };
  closeOffer = close;
  box.addEventListener("click", async (e10) => {
    const v = e10.target.closest("[data-v]")?.dataset.v;
    if (e10.target === box || v === "close") {
      close();
      return;
    }
    if (v === "download") {
      const a10 = document.createElement("a"), url = URL.createObjectURL(file);
      a10.href = url;
      a10.download = file.name;
      document.body.append(a10);
      a10.click();
      a10.remove();
      setTimeout(() => URL.revokeObjectURL(url), 3e4);
      info(`\u5DF2\u4E0B\u8F7D ${file.name}`);
      onDone?.();
      close();
    } else if (v === "share") {
      try {
        await navigator.share({ files: [file], title: file.name });
        info("\u5DF2\u5206\u4EAB");
        onDone?.();
        close();
      } catch (err2) {
        if (err2.name !== "AbortError") showError(`\u5206\u4EAB\u5931\u8D25\uFF1A${err2.message}`);
      }
    }
  });
}
